package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/**
 * The plans on a sheet: listed, added on a person, and generated, each plan date up to the sheet's
 * today making a DRAFT claim by the claim form's rules.
 */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final ClaimService claims;
    private final RoleService roles;
    private final TransactionTemplate eachClaim;
    private final Audit audit;

    public PlanService(PlanRepository plans, PersonRepository people, SheetService sheets,
            SheetRepository sheetStore, ClaimService claims, RoleService roles, PlatformTransactionManager transactions, Audit audit) {
        this.plans = plans;
        this.people = people;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.claims = claims;
        this.roles = roles;
        this.eachClaim = new TransactionTemplate(transactions);
        this.audit = audit;
    }

    /** What a generate made: the claims, in the order they were made, and the sheet's plans after it. */
    public record Generated(List<Claim> claims, List<Plan> plans) {
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today, from which a plan's next dates are counted. */
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    /**
     * Add a plan on a person: an amount (not below 0.00), claimed every N days (at least 1) or monthly on a
     * day of the month (1 to 31), exactly one of the two, from a start date to an end date; refused when the
     * end is before the start. A plan may name one of the sheet's descendants (blank or null: none): its claims
     * are then made on that sheet; one that is not a descendant is refused. PLAN_ADDED then ends with
     * sheet=&lt;that sheet&gt;.
     */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end, String target) {
        if (amount.signum() < 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's amount cannot be below 0.00.");
        }
        if ((every == null) == (day == null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A plan repeats either every N days or monthly on a day of the month.");
        }
        if (day != null && (day < 1 || day > 31)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's day of the month is 1 to 31.");
        }
        if (every != null && every < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan repeats every 1 day or more.");
        }
        if (end.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan cannot end before it starts.");
        }
        String targetSheet = target == null || target.isBlank() ? null : target.trim();
        sheets.lock(sheetId);
        if (targetSheet != null && !sheetStore.descendants(sheetId).contains(targetSheet)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A plan can only name a sheet below this one: " + targetSheet + " is not.");
        }
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        BigDecimal money = amount.setScale(2, RoundingMode.UNNECESSARY);
        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, money, start, every, day, end, targetSheet));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + money.toPlainString() + " start=" + start + (day != null ? " day=" + day : " every=" + every) + " end=" + end
                + (targetSheet != null ? " sheet=" + targetSheet : ""));
        return saved;
    }

    /**
     * Pause a running plan, or resume a paused one, on the sheet's today: a plan date on or after the day
     * paused and before the day resumed is skipped. Pausing a paused plan or resuming a running one is refused.
     */
    @Transactional
    public Plan pause(String sheetId, String user, long planId, boolean on) {
        Sheet sheet = sheets.lock(sheetId);
        Plan plan = plans.findByIdAndSheetId(planId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan on this sheet."));
        if (plan.isPaused() == on) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    on ? "The plan is paused already." : "The plan is not paused.");
        }
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (on) {
            plan.pause(sheet.getToday());
        } else {
            plan.resume(sheet.getToday());
        }
        Plan saved = plans.saveAndFlush(plan);
        audit.recordOnCommit((on ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStart());
        return saved;
    }

    /**
     * Change a plan's amount (not below 0.00) on the sheet's today: the claims generated from then on take it,
     * those already made keep theirs.
     */
    @Transactional
    public Plan changeAmount(String sheetId, String user, long planId, BigDecimal amount) {
        if (amount.signum() < 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A plan's amount cannot be below 0.00.");
        }
        Sheet sheet = sheets.lock(sheetId);
        Plan plan = plans.findByIdAndSheetId(planId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan on this sheet."));
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        BigDecimal money = amount.setScale(2, RoundingMode.UNNECESSARY);
        plan.changeAmount(sheet.getToday(), money);
        Plan saved = plans.saveAndFlush(plan);
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " start=" + plan.getStart() + " amount=" + money.toPlainString());
        return saved;
    }

    /**
     * For every plan on the sheet, in the order they were added, make a DRAFT claim with the plan's amount
     * and an empty note for each plan date up to its end and the sheet's today that has none yet, dated
     * that day. Each claim is added by the claim form's rules, on its own: a date the form refuses is
     * skipped, and tried again on the next generate. A viewer's generate makes nothing: every claim it
     * would make is refused. A plan naming a descendant sheet makes its claims there, by that sheet's rules,
     * for the person there of the plan's person's name: none while there is no such person.
     */
    public Generated generate(String sheetId, String user) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> made = new ArrayList<>();
        if (Role.VIEWER.equals(roles.roleOf(sheetId, user))) {
            return new Generated(made, list(sheetId));
        }
        for (Plan plan : list(sheetId)) {
            for (LocalDate date : plan.datesUpTo(today)) {
                if (plan.hasMade(date)) {
                    continue;
                }
                try {
                    Claim claim = eachClaim.execute(status -> make(sheetId, user, plan.getId(), date));
                    if (claim != null) {
                        made.add(claim);
                    }
                } catch (ResponseStatusException refused) {
                    // the claim form refuses this date for now: it is tried again next time
                }
            }
        }
        return new Generated(made, list(sheetId));
    }

    /** Make the plan's claim for a date, unless another generate already has: null then. */
    private Claim make(String sheetId, String user, long planId, LocalDate date) {
        sheets.lock(sheetId);
        Plan plan = plans.findByIdAndSheetId(planId, sheetId).orElse(null);
        if (plan == null || plan.hasMade(date)) {
            return null;
        }
        Long personId = plan.getPersonId();
        String claimSheet = sheetId;
        if (plan.getTargetSheetId() != null) {
            claimSheet = plan.getTargetSheetId();
            Person own = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElse(null);
            Person there = own == null ? null : people.findBySheetIdAndName(claimSheet, own.getName()).orElse(null);
            if (there == null) {
                return null;
            }
            personId = there.getId();
        }
        Claim claim = claims.add(claimSheet, user, personId, plan.getAmount(), date, "", null);
        plan.made(date, claim.getId());
        plans.saveAndFlush(plan);
        return claim;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * A plan on a person: an amount claimed every N days, or monthly on a day of the month, from its start
 * date up to its end date, both included, with the claims it has made so far by the plan date each was made for.
 */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_on", nullable = false)
    private LocalDate start;

    /** Every N days, or null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan, or null for one every N days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_on", nullable = false)
    private LocalDate end;

    /** The descendant sheet the plan's claims are made on, for the person there of the same name; null: its own. */
    @Column(name = "target_sheet_id")
    private String targetSheetId;

    /** The claims the plan has made, by the plan date each was made for. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_claim", joinColumns = @JoinColumn(name = "plan_id"))
    @MapKeyColumn(name = "on_date")
    @Column(name = "claim_id")
    private Map<LocalDate, Long> made = new TreeMap<>();

    /** The plan's pauses, each from the day paused to the day resumed; the last one open while it is paused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    /** The changes of the plan's amount, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "seq")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        this(sheetId, personId, amount, start, every, day, end, null);
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end, String targetSheetId) {
        this.targetSheetId = targetSheetId;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    /**
     * The plan's dates, oldest first, up to its end and the given day: from its start every N days, or for a
     * monthly plan its day in every month from the start's month (the month's last day when the month is
     * shorter), leaving out those before the start and those skipped by a pause.
     */
    public List<LocalDate> datesUpTo(LocalDate today) {
        LocalDate last = today == null || end.isBefore(today) ? end : today;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
                LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last) && !skipped(d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            if (!skipped(d)) {
                dates.add(d);
            }
        }
        return dates;
    }

    /** The first count plan dates after the given day, oldest first, on or before the plan's end. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        return datesUpTo(null).stream().filter(d -> d.isAfter(today)).limit(count).toList();
    }

    /** Whether a pause skips the plan date: on or after the day paused and before the day resumed. */
    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** Whether the plan is paused now: its last pause has not been resumed. */
    public boolean isPaused() {
        return !pauses.isEmpty() && pauses.get(pauses.size() - 1).isOpen();
    }

    /** Pause the plan from the day; the caller has checked it is running. */
    public void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the plan on the day; the caller has checked it is paused. */
    public void resume(LocalDate on) {
        pauses.get(pauses.size() - 1).resume(on);
    }

    /** Change the plan's amount on the day: the claims made from then on take it, those made keep theirs. */
    public void changeAmount(LocalDate on, BigDecimal amount) {
        this.amount = amount;
        changes.add(new PlanChange(on, amount));
    }

    /** The changes of the plan's amount, oldest first. */
    public List<PlanChange> getChanges() {
        return List.copyOf(changes);
    }

    /** Whether the plan has made a claim for the date. */
    public boolean hasMade(LocalDate date) {
        return made.containsKey(date);
    }

    /** Record the claim the plan made for the date. */
    public void made(LocalDate date, long claimId) {
        made.put(date, claimId);
    }

    /** The plan now belongs to another person, as when its person is merged into them. */
    public void moveTo(long personId) {
        this.personId = personId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    /** Every N days, or null for a monthly plan. */
    public Integer getEvery() {
        return every;
    }

    /** The day of the month of a monthly plan, or null for one every N days. */
    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** The descendant sheet the plan's claims are made on, or null for its own sheet. */
    public String getTargetSheetId() {
        return targetSheetId;
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A change of a plan's amount: the day it was changed on, and the new amount. */
@Embeddable
public class PlanChange {

    @Column(name = "changed_on", nullable = false)
    private LocalDate changedOn;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    protected PlanChange() {
    }

    PlanChange(LocalDate changedOn, BigDecimal amount) {
        this.changedOn = changedOn;
        this.amount = amount;
    }

    public LocalDate getChangedOn() {
        return changedOn;
    }

    public BigDecimal getAmount() {
        return amount;
    }
}
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /**
     * Add a claim (see {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)}) with
     * its tags, comma separated (see {@link Claim#tagsOf}). CLAIM_ADDED ends with tags=&lt;tags, sorted and
     * comma separated&gt; when any were given.
     */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Rollups.Rollup before = rollups.take(sheetId);
        Person person = person(sheetId, personId);
        LocalDate dated = date != null ? date : sheets.load(sheetId).defaultClaimDate();
        Sheet sheet = sheets.lock(sheetId);
        int terms = terms(sheet, person, dated, sheet.getToday());
        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
        // Whether a new claim lands in a closed period is judged by its terms in calendar days from its date.
        periods.refuseIfClosed(sheetId, dated.plusDays(terms));
        refuseIfRetired(person, dated);
        refuseUnlessCorrects(sheetId, personId, amount, corrects, null);
        String referred = reference(ref);
        refuseIfReferred(sheetId, referred, null);
        Claim added = new Claim(sheetId, personId, money(amount), dated, terms, dueBy, clean(note), corrects);
        added.refer(referred);
        List<String> tagged = Claim.tagsOf(tags);
        added.tag(tagged);
        // A claim dated by the sheet's entry date is meant to be dated there: it is late by the sheet's today.
        LocalDate entered = date != null ? date : sheet.getToday();
        if (periods.softClosedOn(sheetId, entered) || periods.softClosedOn(sheetId, dueBy)) {
            added.markLateEntry();
        }
        Claim claim = claims.saveAndFlush(added);
        claim = logged(claim, user, person);
        audited("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
                (referred != null ? " ref=" + referred : "")
                        + (tagged.isEmpty() ? "" : " tags=" + String.join(",", tagged)));
        if (claim.isLateEntry()) {
            audited("LATE_ENTRY", sheetId, user, person, claim);
        }
        rollups.audit(sheetId, user, before);
        return claim;
    }

    /**
     * Change a claim's amount, date, note and the number it corrects; with no date it keeps its own. Only a DRAFT claim can be
     * edited: an OPEN one is changed by voiding it and adding a new one. It keeps the due-by fixed when it
     * was added, and so its period. Refused when the claim's due-by, or a new date plus its terms in
     * calendar days, is inside a closed period, or when it
     * would be a correction that does not name a SETTLED claim of the same person, or when its external
     * reference (null: kept as it is; blank: none) is already used by another claim on the sheet. Its tags
     * (null: kept as they are) are set from the comma separated text (see {@link Claim#tagsOf}).
     */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Rollups.Rollup before = rollups.take(sheetId);
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        refuseUnlessEditable(sheetId, user, claim);
        if (date != null) {
            refuseIfRetired(person(sheetId, claim.getPersonId()), date);
            if (!date.equals(claim.getDate())) {
                periods.refuseIfClosed(sheetId, date.plusDays(claim.getTerms()));
            }
        }
        if (!claim.getLines().isEmpty() && money(amount).compareTo(claim.getAmount()) != 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim with lines takes its amount from them: " + claim.getAmount().toPlainString() + ".");
        }
        refuseUnlessCorrects(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
        String referred = ref == null ? claim.getRef() : reference(ref);
        refuseIfReferred(sheetId, referred, claim.getId());
        claim.refer(referred);
        if (tags != null) {
            claim.tag(Claim.tagsOf(tags));
        }
        claim.change(money(amount), date != null ? date : claim.getDate(), clean(note), corrects);
        claim.lockFor(null);
        claim.editedBy(user);
        Claim saved = claims.saveAndFlush(claim);
        audited("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Add a line to a DRAFT claim: a label, a quantity (at least 1) and a unit amount (two decimals); the
     * claim's amount becomes its lines' quantities times their unit amounts, added up. It counts as an
     * edit of the claim, refused as one is (see {@link #refuseUnlessEditable}), and is audited as
     * CLAIM_LINE_ADDED with the claim's new amount, ending label=&lt;label&gt; qty=&lt;qty&gt; unit=&lt;unit&gt;.
     */
    @Transactional
    public Claim addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
        String trimmed = clean(label);
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A line needs a label.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        sheets.lock(sheetId);
        Claim claim = claim(sheetId, claimId);
        refuseUnlessEditable(sheetId, user, claim);
        BigDecimal unitAmount = money(unit);
        claim.addLine(trimmed, qty, unitAmount);
        claim.editedBy(user);
        Claim saved = claims.saveAndFlush(claim);
        audited("CLAIM_LINE_ADDED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
                " label=" + trimmed + " qty=" + qty + " unit=" + unitAmount.toPlainString());
        rollups.audit(sheetId, user, before);
        return saved;
    }

